// Phase 18G — pre-flight validation. Stop safely BEFORE wp-draft
// if required editorial fields are missing. Returns canonical
// envelope with pipeline_status='held_for_content' in that case.
const up = $json;
const required = ['title_th', 'body_th'];
const missing = required.filter(k => !up[k] || String(up[k]).trim() === '');
if (missing.length > 0) {
  return [{
    json: {
      ...up,
      pipeline_stage: 'wp_draft',
      pipeline_status: 'held_for_content',
      validation_error: 'missing_required_fields',
      missing_fields: missing,
    },
  }];
}
// All required fields present. Proceed.
return [{
  json: {
    ...up,
    pipeline_stage: 'wp_draft',
    pipeline_status: 'accepted',
  },
}];

// Phase 18G — terminal promote. Re-emits canonical envelope with
// wp_post_id + wp_post_status='draft' from the wp-draft response.
//
// Pull wp-draft response via cross-node ref so we capture wp_post_id.
const up = $json;
const draftResp = $('POST /api/automation/wp-draft').item.json || {};
return [{
  json: {
    ...up,
    run_id: up.run_id || draftResp.run_id || null,
    editorial_item_id: up.editorial_item_id || draftResp.editorial_item_id || null,
    wp_post_id: draftResp.wp_post_id || null,
    wp_post_status: draftResp.status === 'draft' ? 'draft' : 'draft',  // hardcoded
    pipeline_stage: 'wp_draft',
    pipeline_status: up.pipeline_status || 'waiting_approval',
  },
}];
